-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH srp_deduped AS ( SELECT DISTINCT s.mri_session_id, s.route_id, s.os, s.channel, s.user_type, CASE WHEN channel_exp_info IS NULL THEN 'null' WHEN contains(channel_exp_info, 'priceVariantAB:V0') THEN 'V0' WHEN contains(channel_exp_info, 'priceVariantAB:V1') THEN 'V1' WHEN contains(channel_exp_info, 'priceVariantAB:V2') THEN 'V2' WHEN contains(channel_exp_info, 'priceVariantAB:V3') THEN 'V3' WHEN contains(channel_exp_info, 'priceVariantAB:V4') THEN 'V4' ELSE 'others' END AS exp_Variant, date_format(at_timezone(s.__time, 'Asia/Kolkata'), '%Y-%b') AS month_period FROM "user_interaction"."search_route_details" s -- JOIN piligrim_dest_list p ON p.dest_id = s.dest_id WHERE s.__time >= TIMESTAMP '2026-05-21 18:30:00' AND s.__time < TIMESTAMP '2026-05-31 18:30:00' -- AND s.os = 'Android' AND s.country = 'IND' AND channel_exp_info IS NOT NULL -- AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.channel IN ('MOBILE_WEB', 'WEB_DIRECT') AND akamai_bot IS NULL AND tp_channel = 'INVALID' -- AND CAST(src_id AS VARCHAR) || '-' || CAST(dest_id AS VARCHAR) IN ('462-122', '462-124', '462-130', '462-210', '462-222', '462-237', '462-255', '462-309', '462-311', '462-313', '462-362', '462-445', '462-450', '462-472', '462-473', '462-530', '462-545', '462-551', '462-571', '462-572', '462-574', '462-575', '462-579', '462-580', '462-624', '462-641', '462-646', '462-647', '462-750', '462-792', '462-979', '462-1003', '462-1007', '462-1008', '462-1021', '462-1142', '462-1476', '462-1571', '462-1588', '462-65976', '462-71255', '462-76079', '462-83409', '462-86833', '462-95083', '462-95217', '462-95220', '462-95222') ), ui_session_flags AS ( -- Aggregate UI events to session level to prevent row duplication SELECT mri_session_id, MAX(CASE WHEN event_name = 'SL loaded' THEN 1 ELSE 0 END) as sl_Land, MAX(CASE WHEN event_value = 'Yes' THEN 1 ELSE 0 END) as Price_range FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-05-31 18:30:00' -- AND header_bu = 'BUS' AND selected_country = 'India' -- AND event_src = 'Android' -- AND event_name IN ('SL loaded') AND event_group = 'ab_exp_srp_price' GROUP BY 1 ), sl_deduped AS ( SELECT mri_session_id, route_id FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-05-31 18:30:00' AND country = 'IND' GROUP BY 1,2 ), mpax_deduped AS ( SELECT mri_session_id, route_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-05-31 18:30:00' AND country = 'IND' GROUP BY 1,2 ), orderinfo_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."order_info_details" WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-05-31 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), confirm_deduped AS ( SELECT mri_session_id, route_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-05-31 18:30:00' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) SELECT -- srp.month_period || 'May 22 to 25' AS month_period, COALESCE(srp.os, srp.channel) AS saleschannel, srp.exp_Variant, srp.user_type, -- CASE WHEN u.SRP_BP_selection_loaded = 1 THEN 'Yes' ELSE 'No' END AS SRP_BP_selection_loaded, -- CASE WHEN u.SRP_BP_selected = 1 THEN 'Yes' ELSE 'No' END AS Bottom_Sheet_Interacted, -- CASE WHEN u.added_BP_names = 1 OR u.removed_BP_names = 1 THEN 'Yes' ELSE 'No' END AS LMB_Interacted, -- CASE WHEN u.SRP_BP_selection_closed = 1 THEN 'Yes' ELSE 'No' END AS SRP_BP_selection_closed, COUNT(DISTINCT srp.mri_session_id) AS srpload, COUNT(DISTINCT sl.mri_session_id) AS slload, COUNT(DISTINCT CASE WHEN sl_Land = 1 THEN sl.mri_session_id END) AS exp_sl_Lands, COUNT(DISTINCT CASE WHEN sl_Land = 1 AND Price_range = 1 THEN sl.mri_session_id END) AS Price_range_sl_Lands, COUNT(DISTINCT pax.mri_session_id) AS CustInfoload, COUNT(DISTINCT oi.mri_session_id) AS paymentload, COUNT(DISTINCT conf.mri_session_id) AS confirmsession, SUM(conf.tin_count) AS tin FROM srp_deduped srp LEFT JOIN sl_deduped sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN ui_session_flags u ON srp.mri_session_id = u.mri_session_id LEFT JOIN mpax_deduped pax ON srp.mri_session_id = pax.mri_session_id AND srp.route_id = pax.route_id LEFT JOIN orderinfo_deduped oi ON srp.mri_session_id = oi.mri_session_id AND srp.route_id = oi.route_id LEFT JOIN confirm_deduped conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id WHERE 1 = 1 -- AND sl_Land = 1 AND Price_range = 1 AND srp.exp_Variant IN ('V0', 'V1', 'V2', 'V3', 'V4') GROUP BY 1, 2 , 3, 4 -- , 5, 6, 7 ORDER BY 2, 3, 4 DESC, 5 DESC
